function readStorage(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return v??fallback;}catch{return fallback;}}
let state={patients:readStorage('opd-patients',seedPatients),users:readStorage('opd-users',seedUsers),logs:readStorage('opd-logs',seedLogs),decisions:readStorage('opd-decisions',[]),scenarios:readStorage('opd-scenarios',[]),wizard:readStorage('opd-wizard',[]),role:sessionStorage.getItem('opd-role')||'Quản trị viên',page:'dashboard',patientId:seedPatients[0].id,search:'',status:'Tất cả',priority:'Tất cả',dept:'Tất cả',pageNumber:1,userSearch:'',userRole:'Tất cả',userStatus:'Tất cả',userTab:'users',period:'Hôm nay',metric:'Theo số bệnh nhân',aiIndex:0,wizardStep:0,sim:{count:1248,queue:'Static',ai:true,hours:8,resources:[4,12,6,4,3],scenario:0,progress:0,running:false,result:null},logSearch:''};
