function persist(){localStorage.setItem('opd-patients',JSON.stringify(state.patients));localStorage.setItem('opd-users',JSON.stringify(state.users));localStorage.setItem('opd-logs',JSON.stringify(state.logs));localStorage.setItem('opd-decisions',JSON.stringify(state.decisions));localStorage.setItem('opd-scenarios',JSON.stringify(state.scenarios));localStorage.setItem('opd-wizard',JSON.stringify(state.wizard));}
function log(type,detail,object='—'){state.logs.unshift({time:new Date().toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Ho_Chi_Minh'}),actor:'Nguyễn Thị Lan',type,detail,object});persist();}
function initials(name){return name.split(' ').slice(-2).map(x=>x[0]).join('');}
const avatar=(name,n=0)=>`<span class="avatar v${n%4}">${esc(initials(name))}</span>`;
const statusColor=s=>s==='Đang chờ'?'red':s==='Đang làm CLS'?'amber':s==='Hoàn tất'?'green':'';
const priorityColor=s=>s==='Cao'?'red':s==='Thấp'?'green':'';
const navItems=[['dashboard','home','Tổng quan'],['patients','users','Theo dõi bệnh nhân'],['ai','spark','Gợi ý AI'],['simulation','chart','Mô phỏng'],['wizard','wand','SAS Wizard'],['users','users','Người dùng & Phân quyền'],['logs','file','Nhật ký hệ thống']];
state.patientId=sessionStorage.getItem('opd-patient-id')||state.patientId;
function navigate(page){if(page==='detail')sessionStorage.setItem('opd-patient-id',state.patientId);location.hash=page; if(state.page===page)render();}
function syncRoute(){const route=location.hash.slice(1)||'dashboard';state.page=['dashboard','patients','ai','simulation','wizard','users','logs','login','detail'].includes(route)?route:'dashboard';if(state.page==='users'&&state.role!=='Quản trị viên')state.page='dashboard';render();}
function heading(title,description,actions=''){return `<div class="page-heading"><div><div class="page-kicker">SMART OPD / ${state.page==='dashboard'?'TRUNG TÂM ĐIỀU HÀNH':esc(title)}</div><h1>${title}</h1><p>${description}</p></div>${actions||'<div class="page-date">Thứ Tư, 14 tháng 10, 2026<strong>Hồ sơ ngoại trú</strong><span class="live"><i class="dot"></i> Khoa Khám bệnh</span></div>'}</div>`;}
function shell(body){return `<aside class="sidebar" id="sidebar">${brand()}<div class="nav-label">KHÔNG GIAN LÀM VIỆC</div><nav class="nav" aria-label="Điều hướng chính">${navItems.filter(x=>x[0]!=='users'||state.role==='Quản trị viên').map(([id,ico,label])=>`<button class="nav-item ${state.page===id||(id==='patients'&&state.page==='detail')?'active':''}" data-action="${id}" ${state.page===id?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${id==='ai'?'<span class="nav-counter">'+state.patients.filter(p=>p.status!=='Hoàn tất'&&!state.decisions.some(d=>d.patientId===p.id)).length+'</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom">${hospitalArt()}<div class="side-caption"><strong>Vận hành thông minh.<br>Vì người bệnh.</strong><br>Vì một bệnh viện hiệu quả hơn.</div><div class="side-footer"><span>SMART OPD · v1.0</span><span>${icon('hospital')} OPD</span></div></div></aside><div class="shell"><header class="topbar"><button class="mobile-toggle" data-action="menu" aria-label="Mở menu">${icon('menu')}</button><form class="search global-search" id="global-search">${icon('search')}<input name="q" aria-label="Tìm kiếm toàn hệ thống" placeholder="Tìm bệnh nhân, mã hồ sơ, phòng khám..."></form><div class="top-actions"><button class="bell" data-action="notifications" aria-label="Thông báo hàng đợi">${icon('bell')}<b>${state.patients.filter(p=>p.status!=='Hoàn tất'&&p.wait>30).length}</b></button><select class="role-select" id="role-select" aria-label="Vai trò hiện tại">${['Quản trị viên','Điều phối viên','Bác sĩ'].map(r=>`<option ${r===state.role?'selected':''}>${r}</option>`).join('')}</select><button class="profile" data-action="profile"><span class="avatar doctor">👩🏻‍⚕️</span><span><strong>${state.role==='Bác sĩ'?'BS. ':''}Nguyễn Thị Lan</strong><small>${state.role==='Bác sĩ'?'Khoa Khám bệnh':state.role==='Quản trị viên'?'Quản trị viên hệ thống':'Phòng Điều phối'}</small></span>${icon('down')}</button></div></header><main class="main">${body}<footer class="content-footer"><span>© 2026 Smart OPD · Quản lý khám ngoại trú</span><span><button data-action="system-info">${icon('info')} Thông tin hệ thống</button> ${icon('shield')}</span></footer></main></div>`;}
function render(){document.title=(navItems.find(x=>x[0]===state.page)?.[2]|| (state.page==='login'?'Đăng nhập':'Chi tiết bệnh nhân'))+' · Smart OPD';const pages={dashboard,patients,detail,ai,simulation,wizard,users,logs};$('#app').innerHTML=state.page==='login'?login():shell((pages[state.page]||dashboard)());bindPage();}
function spark(color='#0ab789'){return `<svg class="spark" viewBox="0 0 60 30"><path d="M1 26 8 22 15 24 23 15 30 17 39 7 46 10 52 3 60 0" fill="none" stroke="${color}" stroke-width="1.6"/></svg>`;}
function stat(label,value,ico,color,trend,sub,unit=''){return `<div class="stat ${color}"><div class="stat-top">${circle(ico,color)}<span class="stat-label">${label}</span></div><div class="stat-value">${value}${unit?` <small>${unit}</small>`:''}</div>${spark(color==='red'?'#fa526d':color==='purple'?'#8755ed':'#0ab789')}<div class="stat-footer"><span class="trend ${color==='red'?'bad':''}">${trend}</span><span>${sub}</span></div></div>`;}
function lineChart(variant=0){const ys=variant===1?[135,130,125,120,126,112,115,112,115,107,101,109,120]:[143,132,118,105,82,97,92,72,89,77,98,112];const points=ys.map((y,i)=>`${45+i*36},${y}`).join(' ');return `<svg class="chart" viewBox="0 0 470 195" role="img" aria-label="Biểu đồ xu hướng theo giờ"><defs><linearGradient id="area${variant}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#62b5ff" stop-opacity=".25"/><stop offset="1" stop-color="#62b5ff" stop-opacity=".02"/></linearGradient></defs>${[20,55,90,125,160].map((y,i)=>`<path d="M30 ${y}H455" stroke="#edf2f8"/><text x="3" y="${y+4}">${150-i*30}</text>`).join('')}${[45,117,189,261,333,405,450].map(x=>`<path d="M${x} 20V160" stroke="#f2f5fa"/>`).join('')}<path d="M45 132 81 114 117 87 153 98 189 69 225 88 261 78 297 45 333 58 369 34 405 83 441 101" stroke="#a8b9d1" fill="none" stroke-dasharray="5 5" stroke-width="2"/><polygon points="45,160 ${points} 441,160" fill="url(#area${variant})"/><polyline points="${points}" fill="none" stroke="#1684ff" stroke-width="2.3"/>${ys.map((y,i)=>`<circle cx="${45+i*36}" cy="${y}" r="3.4" fill="#1684ff" stroke="white" stroke-width="1.4"><title>${i+7} giờ: ${Math.round((160-y)*1.4)} bệnh nhân</title></circle>`).join('')}${['7h','8h','9h','10h','11h','12h','13h','14h','15h','16h','17h','18h'].map((x,i)=>`<text x="${39+i*36}" y="183">${x}</text>`).join('')}</svg>`;}
function barChart(labels=['Tuần 1','Tuần 2','Tuần 3','Tuần 4'],a=[980,1022,1145,1201],b=[1124,1367,1562,1748]){let max=Math.max(...a,...b)*1.18;let width=380/labels.length;return `<svg class="chart" viewBox="0 0 450 195" role="img" aria-label="Biểu đồ so sánh ${labels.join(', ')}"><defs><linearGradient id="bars" x2="0" y2="1"><stop stop-color="#2688ff"/><stop offset="1" stop-color="#6ab2ff"/></linearGradient></defs>${[25,70,115,160].map(y=>`<path d="M35 ${y}H440" stroke="#edf2f8"/>`).join('')}${labels.map((l,i)=>{let x=42+i*width,ha=a[i]/max*140,hb=b[i]/max*140;return `<rect x="${x+6}" y="${160-ha}" width="${width*.28}" height="${ha}" rx="3" fill="#cbd7e3"/><rect x="${x+8+width*.3}" y="${160-hb}" width="${width*.28}" height="${hb}" rx="3" fill="url(#bars)"/><text x="${x+7}" y="${153-ha}">${a[i].toLocaleString('vi-VN')}</text><text x="${x+9+width*.3}" y="${153-hb}">${b[i].toLocaleString('vi-VN')}</text><text x="${x+10}" y="184">${l}</text>`}).join('')}</svg>`;}
function donut(){return `<div class="donut-wrap"><div class="donut"><div class="donut-center"><strong>1.248</strong><small>bệnh nhân</small></div></div><div class="donut-legend">${[['Đang chờ khám',286,22,'#167cff'],['Đang khám',412,33,'#0fb98b'],['Đang cận lâm sàng',318,25,'#ffbd3f'],['Hoàn tất',196,16,'#8c51ef'],['Hủy / Không đến',36,3,'#a6b5ca']].map(([t,n,p,c])=>`<div><i class="dot" style="color:${c}"></i><span>${t}</span><b>${n}</b><small>${p}%</small></div>`).join('')}</div></div>`;}
const departmentsData=[['Khám nội tổng quát',286,210,24,40,'stethoscope'],['Khám ngoại',198,162,32,28,'activity'],['Sản phụ khoa',156,128,26,35,'shield'],['Nhi khoa',142,118,20,42,'users'],['Tai mũi họng',126,98,34,25,'heart']];
function dashboard(){const admin=state.role==='Quản trị viên';return heading(`Chào mừng, ${admin?'Quản trị viên ':state.role==='Bác sĩ'?'Bác sĩ ':''}Nguyễn Thị Lan <span style="font-size:23px">👋</span>`,admin?'Tổng quan toàn hệ thống Smart OPD — Giám sát vận hành, hiệu suất, an toàn và tuân thủ.':state.role==='Điều phối viên'?'Bảng điều phối vận hành hàng đợi — Chủ động điều phối, tối ưu luồng bệnh nhân.':'Theo dõi hành trình khám bệnh và hỗ trợ chăm sóc người bệnh mỗi ngày.')+`<div class="stats">${stat('Tổng bệnh nhân hôm nay','1.248','users','','↑ +12%','so với hôm qua')}${stat('Ca khám hoàn tất','892','check','green','↑ +18%','so với hôm qua')}${stat('Thời gian chờ trung bình','28','clock','teal','↓ −32%','so với tuần trước','phút')}${stat('Mức cải thiện nhờ AI','41%','chart','green','↑ +8%','so với tháng trước')}${stat('Số phòng quá tải','3 <small>/ 18</small>','alert','red','↑ +1','so với hôm qua')}${stat('Độ ổn định hệ thống','99,8%','shield','purple','● Ổn định','hoạt động liên tục')}</div><div class="card toolbar"><div class="tabs">${['Hôm nay','Tuần này','Tháng này','Quý này'].map(t=>`<button class="tab ${state.period===t?'active':''}" data-period="${t}">${t}</button>`).join('')}</div><select id="dashboard-dept" aria-label="Khoa khám"><option>Tất cả khoa khám</option>Khoa Nội tổng quát</option>Khoa Ngoại</option>Khoa Nhi</option></select><select id="dashboard-shift" aria-label="Ca trực"><option>Tất cả ca trực</option>Ca sáng</option>Ca chiều</option></select><input class="input" type="date" value="2026-10-14" aria-label="Ngày báo cáo" id="dashboard-date">${button('Xuất báo cáo','export-dashboard','primary','download')}</div>${state.period!=='Hôm nay'?`<div class="notice">${icon('calendar')} Báo cáo mẫu theo ${state.period.toLowerCase()} — số liệu tổng hợp minh họa.</div>`:''}${state.role==='Điều phối viên'?queueOverview():''}<div class="charts-row">${card('Xu hướng lưu lượng bệnh nhân theo giờ',`<div class="legend"><span><i></i> Hôm nay</span><span><i class="gray"></i> Hôm qua</span></div>${lineChart(state.period==='Hôm nay'?0:1)}`,badge('Theo giờ','gray',false))}${card('So sánh AI vs Baseline theo tuần',`<div class="legend"><span><i class="gray"></i> Baseline (không có AI)</span><span><i></i> Với AI</span></div>${barChart()}`,badge('Theo tuần','gray',false))}${card('Phân bổ trạng thái bệnh nhân',donut(),badge('Hôm nay','gray',false))}</div><div class="grid cols3" style="margin-bottom:16px">${card('Hiệu suất theo khoa/phòng',`<div class="subtabs">${['Theo số bệnh nhân','Theo thời gian chờ','Tỷ lệ hoàn tất'].map(t=>`<button class="${state.metric===t?'active':''}" data-metric="${t}">${t}</button>`).join('')}</div><div class="table-wrap"><table class="compact"><thead><tr><th>Khoa / Phòng</th><th>${state.metric==='Theo thời gian chờ'?'Chờ TB':'Tổng BN'}</th><th>Đã hoàn tất</th><th>Cải thiện AI</th></tr></thead><tbody>${departmentsData.map(([n,total,done,wait,improve,ico])=>`<tr><td><div class="flex" style="gap:6px">${circle(ico)}${n}</div></td><td>${state.metric==='Theo thời gian chờ'?wait+' phút':state.metric==='Tỷ lệ hoàn tất'?Math.round(done/total*100)+'%':total}</td><td><span style="color:#0ab789">${done}</span> <span class="muted">(${Math.round(done/total*100)}%)</span></td><td>${badge('−'+improve+'%','green',false)}</td></tr>`).join('')}</tbody></table></div>`,moreLink('patients'))}${card('Tình trạng tài nguyên và máy móc',resourcesTable(),moreLink('resources'))}${card('Top cảnh báo vận hành',alerts(),moreLink('notifications'))}</div><div class="grid cols3">${card('Hoạt động gần đây của người dùng',recentActivity(),moreLink('logs'))}${card('Tình hình tuân thủ & bảo mật',securityRows(),moreLink('security','Xem chi tiết'))}${card('Thao tác nhanh',`<div class="quick-grid">${[['Xuất báo cáo','Báo cáo tổng hợp hệ thống','download','export-dashboard',''],['Tạo kịch bản mô phỏng','Dự báo và phân tích tình huống','transfer','simulation',''],['Quản lý người dùng','Phân quyền và tài khoản','users','users','purple'],['Xem audit log','Nhật ký hoạt động hệ thống','file','logs','purple'],['Cấu hình mô phỏng','Thiết lập tham số vận hành','settings','simulation',''],['Danh mục phòng khám','Khoa, phòng và tài nguyên','hospital','resources','']].filter(x=>x[3]!=='users'||admin).map(([t,s,i,a,c])=>`<button class="quick ${c}" data-action="${a}">${icon(i)}<span><strong>${t}</strong><small>${s}</small></span></button>`).join('')}</div>`)}</div>`;}
function resourcesTable(){return `<div class="table-wrap"><table class="compact"><thead><tr><th>Tài nguyên</th><th>Tổng</th><th>Hoạt động</th><th>Trạng thái</th></tr></thead><tbody>${[['Phòng khám',18,15,'users'],['Phòng cận lâm sàng',12,11,'flask'],['Máy X-quang',6,5,'monitor'],['Máy siêu âm',8,7,'monitor'],['Máy xét nghiệm',10,9,'flask'],['Máy CT Scanner',2,2,'database'],['Hệ thống HIS',1,1,'hospital'],['Hệ thống AI',1,1,'spark']].map(([n,t,a,i])=>`<tr><td><span class="flex" style="gap:6px">${circle(i,n==='Hệ thống AI'?'purple':'')}${n}</span></td><td>${t}</td><td>${a} <span class="muted">(${Math.round(a/t*100)}%)</span></td><td>${badge('Ổn định','green')}</td></tr>`).join('')}</tbody></table></div>`;}
function alerts(){return [['10:15','Phòng Xét nghiệm máu đang quá tải','Thời gian chờ ước tính 68 phút','red','Cao'],['10:08','Thiết bị X-quang số 2 ngoại tuyến','Không thể kết nối hệ thống','red','Cao'],['09:52','Thời gian chờ khoa Tai mũi họng','Vượt ngưỡng 30 phút','amber','Trung bình'],['09:40','Số bệnh nhân cần cận lâm sàng tăng','Tăng 40% so với cùng giờ hôm qua','purple','Trung bình'],['09:21','Dung lượng lưu trữ sắp đạt ngưỡng','Đã sử dụng 85% dung lượng','amber','Thấp']].map(([time,t,s,c,b])=>`<div class="list-row">${circle('alert',c)}<div><strong>${t}</strong><small>${s}</small></div>${badge(b,c)}</div>`).join('');}
function recentActivity(){return state.logs.slice(0,5).map((l,i)=>`<div class="list-row"><time>${esc(l.time)}</time>${circle(i%2?'users':'user',i%2?'purple':'')}<div><strong>${esc(l.actor)}</strong><small>${esc(l.detail)}</small></div>${badge(l.type,i%2?'green':'purple',false)}</div>`).join('');}
function securityRows(){return [['Nhật ký truy cập hệ thống','452 lượt truy cập trong dữ liệu mẫu','file','Bình thường',''],['Hoạt động bất thường','0 cảnh báo bảo mật trong dữ liệu mẫu','shield','An toàn','red'],['Sao lưu dữ liệu','Lưu cục bộ tự động trên trình duyệt','database','Đang bật',''],['Tuân thủ quy định y tế','Thông tin minh họa, chưa đánh giá tuân thủ','file','Chưa đánh giá','red']].map(([t,s,i,b,c])=>`<div class="list-row">${circle(i,c)}<div><strong>${t}</strong><small>${s}</small></div>${badge(b,'green',false)}</div>`).join('');}
function queueOverview(){return card('Hàng đợi theo phòng chức năng',`<div class="table-wrap"><table><thead><tr><th>Phòng chức năng</th><th>Đang chờ</th><th>Công suất / giờ</th><th>Thời gian chờ TB</th><th>Trạng thái</th><th>Tiến độ xử lý</th><th>Thao tác</th></tr></thead><tbody>${[['X-quang',42,60,85,70],['Siêu âm',28,50,38,56],['Xét nghiệm máu',96,100,72,78],['Khám nội tổng quát',120,80,54,62]].map(([n,c,cap,w,p])=>`<tr><td><strong>${n}</strong></td><td><strong>${c}</strong> bệnh nhân</td><td>${cap} / giờ</td><td>${badge(w+' phút',w>60?'red':'amber',false)}</td><td>${badge(w>60?'Quá tải':'Bình thường',w>60?'red':'green')}</td><td><div class="flex">${p}%<div class="progress" style="width:100px"><span style="width:${p}%"></span></div></div></td><td><button class="btn soft" data-queue="${n}">Xem hàng đợi</button></td></tr>`).join('')}</tbody></table></div>`,badge('Hàng đợi hiện tại','green'))+'<div style="height:16px"></div>';}
function filteredPatients(){const q=state.search.toLocaleLowerCase('vi');return state.patients.filter(p=>(p.name+' '+p.id+' '+p.phone).toLocaleLowerCase('vi').includes(q)&&(state.status==='Tất cả'||p.status===state.status)&&(state.priority==='Tất cả'||p.priority===state.priority)&&(state.dept==='Tất cả'||p.department===state.dept));}
function patients(){let list=filteredPatients(),pages=Math.max(1,Math.ceil(list.length/10));state.pageNumber=Math.min(state.pageNumber,pages);return heading('Theo dõi bệnh nhân','Quản lý, theo dõi hành trình và điều phối bệnh nhân trong thời gian thực.')+`<section class="card filter-card"><div class="filter-grid"><div class="search">${icon('search')}<input id="patient-search" value="${esc(state.search)}" placeholder="Tìm theo mã BN, họ tên, số điện thoại..." aria-label="Tìm bệnh nhân"></div><select id="patient-status" aria-label="Trạng thái">${['Tất cả','Đang chờ','Đang khám','Đang làm CLS','Hoàn tất'].map(x=>`<option value="${x}" ${x===state.status?'selected':''}>${x==='Tất cả'?'Trạng thái: Tất cả':x}</option>`).join('')}</select><select id="patient-dept" aria-label="Phòng chức năng">${['Tất cả',...new Set(departments)].map(x=>`<option value="${x}" ${x===state.dept?'selected':''}>${x==='Tất cả'?'Tất cả phòng chức năng':x}</option>`).join('')}</select><select id="patient-priority" aria-label="Mức ưu tiên">${['Tất cả','Cao','Bình thường','Thấp'].map(x=>`<option value="${x}" ${x===state.priority?'selected':''}>${x==='Tất cả'?'Tất cả mức ưu tiên':x}</option>`).join('')}</select>${button('Đặt lại','reset-filters','','refresh')}</div><div class="filter-tabs">${['Tất cả','Đang chờ','Đang khám','Đang làm CLS','Hoàn tất'].map(x=>`<button class="filter-chip ${state.status===x?'active':''}" data-status="${x}"><i class="dot" style="color:${x==='Đang chờ'?'#fb5a77':x==='Hoàn tất'?'#0cb88c':x==='Đang làm CLS'?'#f1b024':'#1885ff'}"></i>${x}<b>${x==='Tất cả'?state.patients.length:state.patients.filter(p=>p.status===x).length}</b></button>`).join('')}<span class="small muted" style="margin-left:auto;align-self:center">Hồ sơ ngày 14/10/2026</span></div></section><section class="card"><div class="card-head"><h2>Danh sách bệnh nhân <span class="muted">(${list.length})</span></h2><div class="flex">${button('Xuất CSV','export-patients','','download')}${button('Đăng ký bệnh nhân','new-patient','primary','plus')}</div></div><div class="table-wrap"><table class="patient-table"><thead><tr><th>#</th><th>Mã BN</th><th>Họ tên</th><th>Tuổi</th><th>Giới tính</th><th>Bước hiện tại</th><th>Hoạt động<br>hoàn tất</th><th>Phòng tiếp theo</th><th>Mức ưu tiên</th><th>Thời gian chờ</th><th>Trạng thái</th><th>Hành động</th></tr></thead><tbody>${list.slice((state.pageNumber-1)*10,state.pageNumber*10).map((p,i)=>`<tr><td>${(state.pageNumber-1)*10+i+1}</td><td class="small">${p.id}</td><td><button class="flex name" data-patient="${p.id}">${avatar(p.name,i)}${esc(p.name)}</button></td><td>${p.age}</td><td><span style="color:${p.gender==='Nữ'?'#f3518a':'#2788ff'}">${p.gender==='Nữ'?'♀':'♂'}</span> ${p.gender}</td><td>${badge(p.department,p.department==='X-quang'?'red':p.department==='Siêu âm'?'green':'',false)}</td><td><strong>${p.completed}/21</strong><div class="progress"><span style="width:${p.completed/21*100}%"></span></div></td><td>${esc(p.next)}<small>${esc(p.room)} · Tầng ${i%2+1}</small></td><td>${badge(p.priority,priorityColor(p.priority))}</td><td>${badge(p.wait+' phút',p.wait>40?'red':p.wait>15?'amber':'green')}</td><td>${badge(p.status,statusColor(p.status))}</td><td><div class="actions"><button class="icon-btn" data-patient="${p.id}" aria-label="Xem ${esc(p.name)}">${icon('eye')}</button><button class="icon-btn" data-patient-ai="${p.id}" aria-label="Gợi ý cho ${esc(p.name)}" style="color:#9253ed">${icon('spark')}</button><button class="icon-btn" data-transfer="${p.id}" aria-label="Điều phối ${esc(p.name)}">${icon('transfer')}</button></div></td></tr>`).join('')||'<tr><td colspan="12" class="table-empty">Không tìm thấy bệnh nhân phù hợp. Hãy thử đổi bộ lọc.</td></tr>'}</tbody></table></div><div class="pagination"><span>Hiển thị ${list.length?(state.pageNumber-1)*10+1:0}–${Math.min(state.pageNumber*10,list.length)} / ${list.length} bệnh nhân</span><div class="flex"><button data-page="${Math.max(1,state.pageNumber-1)}" aria-label="Trang trước">‹</button>${Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${state.pageNumber===i+1?'active':''}">${i+1}</button>`).join('')}<button data-page="${Math.min(pages,state.pageNumber+1)}" aria-label="Trang sau">›</button></div></div></section><div class="summary-stats">${card('Thống kê hàng đợi hôm nay',donut(),moreLink('dashboard','Xem chi tiết'))}${card('Tình trạng phòng chức năng',roomTable(),moreLink('resources'))}${card('Thời gian chờ trung bình',`<div class="flex" style="padding:12px 0 22px">${circle('clock','teal')}<div><strong style="font-size:25px">28 phút</strong><p style="font-size:10px;color:#91a2b9"><span class="trend">↓ −32%</span> so với tuần trước</p></div></div><div class="grid cols2" style="border-top:1px solid var(--line);padding-top:18px"><div class="flex">${circle('alert','red')}<div><span class="small muted">Bệnh nhân quá tải</span><h2>46</h2></div></div><div class="flex">${circle('alert','amber')}<div><span class="small muted">Cần chú ý</span><h2>12</h2></div></div></div>`)}</div>`;}
function roomTable(){return `<table class="compact"><thead><tr><th>Phòng chức năng</th><th>Đang có / Công suất</th><th>Tỷ lệ</th></tr></thead><tbody>${[['Khám tổng quát',12,16],['Xét nghiệm',28,40],['Siêu âm',8,12],['X-quang',10,16],['CT Scanner',6,8],['Nhà thuốc',18,24]].map(([n,a,t],i)=>`<tr><td>${n}</td><td><div class="flex">${a} / ${t}<div class="progress" style="width:75px"><span style="width:${a/t*100}%;background:${i===4?'#ffb62a':i%2?'#19bc91':'#388eff'}"></span></div></div></td><td>${Math.round(a/t*100)}%</td></tr>`).join('')}</tbody></table>`;}
function currentPatient(){return state.patients.find(p=>p.id===state.patientId)||state.patients[0];}
const activities=['Đăng ký tiếp nhận','Đo sinh hiệu','Lấy máu xét nghiệm','Lấy mẫu nước tiểu','Khám nội tổng quát','Khám mắt','Khám tai mũi họng','Điện tim (ECG)','X-quang ngực','Siêu âm ổ bụng tổng quát','Khám chuyên khoa','Khám răng hàm mặt','Đánh giá kết quả xét nghiệm','Tư vấn dinh dưỡng','Khám da liễu','Đánh giá chức năng hô hấp','Tư vấn sức khỏe','Tổng hợp kết quả','Thanh toán viện phí','Nhận thuốc','Hoàn tất hồ sơ'];
function detail(){let p=currentPatient();return `<button class="link small" data-action="patients" style="margin-bottom:13px">‹ Quay lại danh sách bệnh nhân</button>`+heading('Chi tiết bệnh nhân','Theo dõi tiến trình, ghi chú và lịch sử điều phối người bệnh.',`<div class="flex detail-actions">${button('Xem gợi ý AI','detail-ai','purple','spark')}${button('Điều phối thủ công','detail-transfer','green','transfer')}${button('In hồ sơ','print','primary','print')}</div>`)+`<section class="card detail-person">${avatar(p.name)}<div><h2>${p.id} — ${esc(p.name)} <span style="color:var(--blue)">${p.gender==='Nữ'?'♀':'♂'}</span></h2><p>Tuổi: ${p.age} &nbsp; | &nbsp; SĐT: ${esc(p.phone)}<br>Gói khám: <span style="color:var(--blue)">Khám sức khỏe tổng quát (21 hạng mục)</span><br>Ngày khám: 14/10/2026</p></div><div class="location">${badge(p.priority,priorityColor(p.priority))} ${badge(p.status,statusColor(p.status))}<p style="margin-top:12px">${icon('pin')} Vị trí hiện tại</p><h3>${esc(p.department)} · ${esc(p.room)}</h3></div></section><div class="grid cols2"><section class="card"><div class="card-head"><h2>Tiến trình khám sức khỏe tổng quát</h2>${badge(p.completed+'/21 hoạt động','green',false)}</div><div class="card-body"><div class="between small muted" style="margin-bottom:10px"><span>${p.completed} hoàn thành · ${21-p.completed} còn lại</span><strong style="color:var(--blue)">${Math.round(p.completed/21*100)}%</strong></div><div class="progress"><span style="width:${p.completed/21*100}%"></span></div></div><div class="timeline">${activities.slice(0,Math.min(21,Math.max(12,p.completed+2))).map((a,i)=>`<div class="timeline-row ${i<p.completed?'done':i===p.completed?'current':''}"><span class="timeline-number">${i<p.completed?'✓':i+1}</span><div><strong>${a}</strong><small>${i<p.completed?'Đã ghi nhận kết quả':i===p.completed?'Đang xử lý tại phòng chức năng':'Theo trình tự khám đã đăng ký'}</small></div><time>${String(8+Math.floor(i/5)).padStart(2,'0')}:${String(i*12%60).padStart(2,'0')}</time>${badge(i<p.completed?'Hoàn thành':i===p.completed?'Đang thực hiện':'Chưa thực hiện',i<p.completed?'green':i===p.completed?'':'gray',false)}</div>`).join('')}</div></section><div class="stack">${card('Hàng đợi & Thời gian chờ',`<table><thead><tr><th>Phòng chức năng</th><th>Đang chờ</th><th>Chờ TB</th></tr></thead><tbody>${[['P. X-quang',3,15],['P. Siêu âm',5,22],['P. Xét nghiệm',12,35],['P. Khám CK 1',4,18]].map(([n,a,w])=>`<tr><td><strong>${n}</strong><small>Tầng 1 · Khu khám bệnh</small></td><td>${a} bệnh nhân</td><td style="color:#0ab789">${w} phút</td></tr>`).join('')}</tbody></table>`)}${card('Hành động tiếp theo',`<div class="list-row">${circle('check','green')}<div><strong>Hoàn thành hoạt động hiện tại</strong><small>Cập nhật tiến trình của bệnh nhân</small></div><button class="btn primary" data-complete="${p.id}" ${p.completed>=21?'disabled':''}>Hoàn thành</button></div><div class="list-row">${circle('transfer')}<div><strong>Chuyển đến phòng khám khác</strong><small>Điều phối theo tình trạng hiện tại</small></div><button class="btn" data-transfer="${p.id}">Chọn phòng</button></div><div class="list-row">${circle('spark','purple')}<div><strong>Gợi ý phương án điều phối</strong><small>So sánh thời gian chờ dự kiến</small></div>${button('Xem gợi ý','detail-ai','purple')}</div>`)}${card('Ghi chú cho bác sĩ / điều phối viên',`<form id="note-form"><label class="field"><span class="small muted">Thông tin cần lưu ý</span><textarea name="note" maxlength="500" required placeholder="Thêm ghi chú, thông tin đặc biệt về bệnh nhân..."></textarea></label><div style="text-align:right;margin-top:10px"><button class="btn primary" type="submit">${icon('save')} Lưu ghi chú</button></div></form>${p.notes.map(n=>`<div class="list-row">${avatar('Nguyễn Thị Lan')}<div><strong>Nguyễn Thị Lan <span class="muted small">${esc(n.time)}</span></strong><small>${esc(n.text)}</small></div></div>`).join('')}`)}${card('Tổng quan & Dự kiến',`<div class="list-row"><span class="muted">Thời gian chờ hiện tại</span><strong style="margin-left:auto">${p.wait} phút</strong></div><div class="list-row"><span class="muted">Phòng tiếp theo dự kiến</span><strong style="margin-left:auto">${esc(p.next)}</strong></div><div class="list-row"><span class="muted">Tiến trình hoàn thành</span><strong style="margin-left:auto;color:var(--green)">${Math.round(p.completed/21*100)}%</strong></div>`)}</div></div>`;}
function aiPatients(){let sorted=state.patients.filter(p=>p.status!=='Hoàn tất').sort((a,b)=>b.wait-a.wait);let result=sorted.slice(0,8);if(state.aiTarget&&!result.some(p=>p.id===state.aiTarget)){let target=state.patients.find(p=>p.id===state.aiTarget);if(target)result=[target,...result.slice(0,7)];}return result;}
function ai(){let list=aiPatients();let p=list[state.aiIndex]||list[0];if(!p)return heading('Gợi ý AI','Hỗ trợ đánh giá và lựa chọn phương án điều phối.')+card('Không có bệnh nhân chờ','<div class="empty">Tất cả bệnh nhân đã hoàn tất.</div>');let existing=state.decisions.find(d=>d.patientId===p.id);return heading('Gợi ý AI','Hỗ trợ điều phối và ra quyết định dựa trên dữ liệu thời gian thực.')+`<div class="notice">${icon('info')} Gợi ý dựa trên quy tắc điều phối. Kiểm tra chuyên khoa và điều kiện tiếp nhận trước khi áp dụng.</div><div class="ai-layout"><section class="card"><div class="card-head"><h2>Bệnh nhân cần quyết định</h2></div><div class="table-top-note">${icon('refresh')} Ưu tiên thời gian chờ cao nhất</div><div class="ai-list">${list.map((x,i)=>`<button class="patient-option ${p.id===x.id?'active':''}" data-ai-index="${i}"><span class="muted small">${i+1}</span><div><strong>${esc(x.name)}</strong><small>#${x.id} · ${x.age} tuổi · ${x.gender}</small><small>${badge(x.priority,priorityColor(x.priority),false)} ${esc(x.department)}</small></div><span class="time">${x.wait}<small>phút</small></span></button>`).join('')}</div></section><div class="stack"><section class="card ai-person"><div class="flex">${avatar(p.name)}<div><h2>${esc(p.name)}</h2><p class="small muted">#${p.id} &nbsp; · &nbsp; ${p.age} tuổi &nbsp; · &nbsp; ${p.gender}</p><p class="small muted" style="margin-top:6px">${esc(p.department)} · ${esc(p.room)}</p></div></div><div>${badge('Thời gian chờ: '+p.wait+' phút','red')}</div></section><section class="recommendation"><div class="between"><h2>${icon('spark')} Hoạt động tiếp theo đề xuất</h2>${badge('Đề xuất điều phối','green')}</div><div class="recommend-inner"><h3>Chuyển bệnh nhân đến Phòng khám Nội tổng quát 2 (P.201)</h3><div class="impact"><div><strong style="color:var(--green)">↓ Giảm ${Math.min(18,Math.max(4,Math.round(p.wait*.3)))} phút</strong><small>thời gian chờ dự kiến</small></div><div><strong>Giảm tải 22%</strong><small>hàng đợi phòng hiện tại</small></div><div><strong style="color:var(--blue)">P.201</strong><small>BS. Trần Minh Hải</small></div></div><div class="explain"><strong style="color:#385d8e">${icon('file')} Cơ sở đề xuất</strong><p style="margin-top:6px">Phương án đang xét giả định phòng P.201 có nguồn lực còn trống và thời gian chờ ngắn hơn. Chuyển phòng giúp cân bằng lượng bệnh nhân giữa các phòng. Điều phối viên cần kiểm tra chuyên khoa và điều kiện thực tế trước khi áp dụng.</p></div>${existing?`<div class="notice" style="margin:16px 0 0">${icon('check')} Đã xử lý: ${esc(existing.status)} · ${esc(existing.reason||'Chuyển đến P.201')}</div>`:`<div class="action-bar">${button('Chấp nhận gợi ý','accept-ai','primary','check')}${button('Ghi đè thủ công','override-ai','','edit')}${button('Từ chối','reject-ai','danger','close')}</div>`}</div></section>${card('So sánh tác động đến hàng chờ (dự kiến)',`<div class="legend"><span><i class="gray"></i> Trước khi áp dụng</span><span><i></i> Sau khi áp dụng</span></div>${barChart(['Nội tổng quát','Tim mạch','Cơ xương khớp','Sản phụ khoa'],[42,28,32,25],[24,26,28,24])}`)}${card('Lịch sử quyết định gần đây',`<div class="table-wrap"><table><thead><tr><th>Thời gian</th><th>Bệnh nhân</th><th>Quyết định</th><th>Chi tiết</th></tr></thead><tbody>${state.decisions.length?state.decisions.slice(0,8).map(d=>`<tr><td>${esc(d.time)}</td><td>${esc(d.name)}</td><td>${badge(d.status,d.status==='Đã chấp nhận'?'green':d.status==='Từ chối'?'red':'purple',false)}</td><td>${esc(d.reason||'Chuyển đến P.201')}</td></tr>`).join(''):'<tr><td colspan="4" class="table-empty">Chưa có quyết định. Chấp nhận hoặc ghi đè một gợi ý để bắt đầu.</td></tr>'}</tbody></table></div>`,moreLink('logs'))}</div></div>`;}
const baseScenarios=[['Cơ sở hiện tại','Phương án vận hành làm mốc so sánh','chart',''],['Tăng 20% bệnh nhân','Kiểm tra khả năng đáp ứng khi lưu lượng tăng','activity','red'],['Bổ sung 2 phòng khám','Đánh giá hiệu quả khi mở rộng','users','purple'],['Ưu tiên bệnh nhân cấp cứu','Hàng đợi ưu tiên theo mức độ','heart','red'],['Sử dụng AI điều phối','Mô phỏng chính sách phân bổ nguồn lực','spark','purple'],['Giảm 30% thời gian xét nghiệm','Ứng dụng thiết bị mới','flask','green']];
function simulation(){let s=state.sim;let r=s.result;return heading('Simulation Studio','Mô phỏng và đánh giá các kịch bản vận hành khoa khám bệnh, hỗ trợ quyết định dựa trên dữ liệu.')+`<div class="sim-top">${card('1. Cấu hình kịch bản mô phỏng',`<div class="range-label"><span>${icon('users')} Số lượng bệnh nhân</span><strong id="patient-count">${s.count.toLocaleString('vi-VN')}</strong></div><input id="sim-count" type="range" min="100" max="5000" step="1" value="${s.count}" aria-label="Số bệnh nhân mô phỏng"><div class="between small muted" style="margin:6px 0 23px"><span>100</span><span>1.000</span><span>2.000</span><span>5.000</span></div><h3 style="font-size:11px">${icon('clock')} Loại hàng đợi</h3><div class="queue-types">${[['Static','Hàng đợi tĩnh (FIFO)'],['Priority','Ưu tiên theo mức độ'],['Random','Phân phối ngẫu nhiên']].map(([t,d])=>`<button class="queue-type ${s.queue===t?'active':''}" data-queue-type="${t}"><strong>${t}</strong><small>${d}</small></button>`).join('')}</div><h3 style="font-size:11px">${icon('shield')} Năng lực phục vụ từng tài nguyên</h3>${['Bàn tiếp đón','Phòng khám','Phòng xét nghiệm','Chẩn đoán hình ảnh','Nhà thuốc'].map((n,i)=>`<div class="resource-control"><span>${n}</span><input data-resource="${i}" type="range" min="1" max="${i===1?30:12}" value="${s.resources[i]}" aria-label="${n}"><b id="resource-${i}">${s.resources[i]}</b></div>`).join('')}<label class="flex" style="font-size:10px;margin-top:22px"><input type="checkbox" id="sim-ai" class="switch" ${s.ai?'checked':''}><strong>Chính sách AI</strong><span class="muted">Áp dụng hệ số tối ưu</span></label>`,button('Đặt lại','reset-sim','','refresh'))}${card('2. Kịch bản có sẵn',`<div>${[...baseScenarios,...state.scenarios.map(x=>[x.name,'Kịch bản đã lưu','save',''])].map(([n,d,i,c],idx)=>`<button class="scenario ${s.scenario===idx?'active':''}" data-scenario="${idx}">${circle(i,c)}<span><strong>${esc(n)}</strong><small>${d}</small></span></button>`).join('')}</div><div style="border-top:1px solid var(--line);margin-top:14px;padding-top:15px"><h3 style="font-size:11px">${icon('clock')} Thời gian mô phỏng</h3><div class="flex" style="margin-top:12px">${[4,8,12,24].map(h=>`<button class="btn ${s.hours===h?'soft':''}" data-hours="${h}">${h} giờ</button>`).join('')}</div></div>`,button('Tạo mới','new-scenario','','plus'))}${card('3. Điều khiển mô phỏng',`<div class="grid cols2">${button(s.running?'Đang chạy':s.progress>0&&s.progress<100?'Tiếp tục':'Chạy mô phỏng','run-sim','primary','play')}${button('Tạm dừng','pause-sim','','pause')}${button('Lưu kịch bản','save-scenario','','save')}${button('Xuất kết quả','export-sim','','download')}</div><div class="sim-progress"><div class="between"><h3>Tiến trình công việc</h3><span id="sim-status">${badge(s.running?'Đang chạy':s.progress===100?'Hoàn thành':'Sẵn sàng',s.running||s.progress===100?'green':'gray',false)}</span></div><p class="small muted" style="margin-bottom:15px">Mô phỏng ${s.count.toLocaleString('vi-VN')} bệnh nhân trong ${s.hours} giờ</p><div class="between"><div class="progress" style="flex:1"><span id="sim-bar" style="width:${s.progress}%"></span></div><strong id="sim-percent" style="color:var(--blue)">${s.progress}%</strong></div><div class="list-row"><span class="small muted">Phương pháp</span><strong style="margin-left:auto">${s.queue}</strong></div><div class="list-row"><span class="small muted">Chính sách tối ưu</span><strong style="margin-left:auto">${s.ai?'Bật':'Tắt'}</strong></div><p class="small muted" style="margin-top:15px">Kết quả phụ thuộc cấu hình và giả định của mô hình.</p></div>`)}</div><section class="card" style="padding:18px"><div class="between"><h2>Kết quả mô phỏng</h2>${badge(r?'Kết quả từ cấu hình đã chạy':'Chưa chạy mô phỏng',r?'green':'gray',false)}</div>${r?`<div class="stats sim-stats" style="margin-top:16px">${stat('LoS trung bình',r.los,'clock','green','↓ −'+r.improvement+'%','so với baseline','phút')}${stat('Thời gian chờ trung bình',r.wait,'users','','↓ −'+r.improvement+'%','so với baseline','phút')}${stat('Tỷ lệ quá tải',r.overload+'%','alert','red','Mô phỏng','theo công suất')}${stat('Số bệnh nhân hoàn tất',r.completed.toLocaleString('vi-VN'),'flag','purple',Math.round(r.completed/r.count*100)+'%','tổng bệnh nhân')}</div><div class="grid cols3">${card('Thời gian chờ theo giờ',lineChart(1))}${card('Lưu lượng theo phòng chức năng',barChart(['Tiếp đón','Khám','Xét nghiệm','CĐHA'],[310,280,220,160],[Math.round(r.completed*.26),Math.round(r.completed*.23),Math.round(r.completed*.18),Math.round(r.completed*.13)]))}${card('Bản đồ nhiệt hàng đợi',heatmap(r.wait))}</div>`:`<div class="empty">${icon('chart')}<h3>Sẵn sàng khám phá kịch bản vận hành</h3><p>Chọn cấu hình và nhấn “Chạy mô phỏng” để so sánh hiệu quả.</p></div>`}</section>`;}
function heatmap(wait){return `<div class="heatmap">${['Tiếp đón','Khám bệnh','Xét nghiệm','Chẩn đoán HA','Nhà thuốc'].map((n,i)=>`<span>${n}</span>${Array.from({length:12},(_,j)=>{let load=(i*13+j*7+wait)%60;return `<i style="background:${load<20?'#94dbc0':load<35?'#d1e9a2':load<47?'#ffe08d':'#ffad91'}" title="${n}, ${j+7}h: ${load} bệnh nhân"></i>`}).join('')}`).join('')}<span></span>${Array.from({length:12},(_,i)=>`<span>${i+7}h</span>`).join('')}</div><div class="small muted" style="text-align:center;margin-top:15px">Thấp <span style="color:#91dabc">■■■</span><span style="color:#dce89e">■■■</span><span style="color:#ffdb8a">■■■</span><span style="color:#ffad91">■■■</span> Cao</div>`;}
const questions=[['Quy trình hiện tại có linh hoạt theo thiết kế không?','Quy trình được coi là linh hoạt theo thiết kế nếu có nhiều lựa chọn về thứ tự, nguồn lực, thời gian hoặc cách thực hiện cho mỗi bước.','Linh hoạt theo thiết kế','Trong khám bệnh, người bệnh có thể được khám bởi nhiều bác sĩ phù hợp, đổi thứ tự các bước không phụ thuộc nhau hoặc chuyển phòng khi quá tải.'],['Có thể tái thiết kế quy trình thành linh hoạt không?','Đánh giá khả năng thay đổi thứ tự hoạt động, phân bổ tài nguyên hoặc mở rộng các lựa chọn hiện có.','Khả năng tái thiết kế','Có thể bổ sung một phòng khám tương đương, điều chỉnh lịch hẹn hoặc phân bổ lại nhân sự giữa các ca.'],['Số lượng hoạt động đồng thời có lớn không?','Xem xét số bệnh nhân, phòng chức năng và các bước xử lý đang diễn ra cùng lúc.','Hoạt động đồng thời','Nhiều hàng đợi cùng thay đổi và nhiều phòng khám cùng phục vụ làm tăng số tổ hợp quyết định cần xem xét.'],['Không gian hành động có thể mở rộng không?','Đánh giá khả năng bổ sung lựa chọn điều phối hoặc tài nguyên khi hệ thống thay đổi.','Không gian hành động','Hệ thống có thể mở thêm phòng, phân công thêm nhân sự hoặc thêm cách sắp xếp thứ tự khám.'],['Môi trường vận hành có tính ngẫu nhiên cao không?','Xem xét mức biến động của thời gian khám, lượng bệnh nhân đến và sự sẵn có của tài nguyên.','Môi trường ngẫu nhiên','Bệnh nhân đến không theo lịch cố định, thời gian khám thay đổi hoặc thiết bị có thể tạm ngừng hoạt động.']];
function wizardRecommendation(){let score=state.wizard.reduce((a,b)=>a+(b===0?2:b===1?1:0),0);return score>=7?['Học tăng cường (RL)','Phù hợp để nghiên cứu khi môi trường có nhiều lựa chọn, nhiều hoạt động đồng thời và biến động lớn. Cần dữ liệu, mô phỏng và kiểm chứng trước khi triển khai.']:score>=3?['Heuristic kết hợp mô phỏng','Bắt đầu bằng các quy tắc ưu tiên và cân bằng hàng đợi. Dùng mô phỏng để so sánh và điều chỉnh tham số theo bối cảnh.']:['Tối ưu toán học / Quy tắc tĩnh','Quy trình có ít lựa chọn hoặc còn nhiều ràng buộc cố định. Có thể bắt đầu từ lập lịch có ràng buộc và hàng đợi FIFO.'];}
function wizard(){let step=state.wizardStep,q=questions[Math.min(step,4)],complete=step===5,answered=state.wizard.filter(x=>x!==null&&x!==undefined).length,rec=wizardRecommendation();return heading('SAS Wizard','Trả lời 5 câu hỏi để nhận gợi ý phương pháp ra quyết định phù hợp cho bài toán của bạn.',button('Hướng dẫn sử dụng','wizard-help','','play'))+`<section class="card wizard-steps">${questions.map((x,i)=>`<button class="wizard-step ${step===i?'active':''} ${state.wizard[i]!==undefined&&state.wizard[i]!==null?'done':''}" data-wizard-step="${i}"><span>${state.wizard[i]!==undefined&&state.wizard[i]!==null?'✓':i+1}</span><small>Q${i+1}<br>${x[2]}</small></button>`).join('')}</section><div class="wizard-layout"><section class="card wizard-intro"><h2>SAS Wizard là gì?</h2><p>Công cụ hỗ trợ đánh giá nhanh đặc điểm bài toán vận hành và gợi ý phương pháp ra quyết định: học tăng cường, heuristic hoặc tối ưu toán học.</p><div class="robot">🤖</div><h3>Vì sao cần đánh giá?</h3>${['Hiểu rõ đặc điểm bài toán vận hành','Chọn phương pháp phù hợp, tiết kiệm thời gian','Đánh giá khả năng mở rộng của quy trình','Tạo cơ sở cho việc thiết kế mô phỏng'].map(x=>`<div class="check-item">${icon('check')}<span>${x}</span></div>`).join('')}<div class="notice" style="margin-top:22px">${icon('clock')} Thời gian hoàn thành<br>Khoảng 3–5 phút với 5 câu hỏi.</div></section><section class="card question"><div class="between small muted"><strong>Câu ${Math.min(step+1,5)} / 5</strong><div class="progress" style="flex:1;margin:0 10px"><span style="width:${complete?100:(step+1)*20}%"></span></div><span>${complete?100:(step+1)*20}%</span></div>${complete?`<div class="result-illustration">🎯</div><h2>Đã hoàn thành đánh giá</h2><p>Kết quả được tổng hợp từ 5 câu trả lời của bạn. Kết quả là gợi ý tham khảo dựa trên đặc điểm quy trình.</p><div class="explain"><h2 style="color:var(--blue);margin-top:0">${rec[0]}</h2><p>${rec[1]}</p></div><div class="action-bar">${button('Làm lại đánh giá','restart-wizard','','refresh')}${button('Mở mô phỏng','simulation','primary','chart')}</div>`:`<h2>${q[0]}</h2><p>${q[1]}</p>${[['Có, đáp ứng rõ ràng','Có nhiều lựa chọn và điều kiện phù hợp với mô tả.'],['Một phần, có một số giới hạn','Đáp ứng một phần nhưng vẫn có các ràng buộc.'],['Không, chưa đáp ứng','Quy trình hiện tại không có đặc điểm này.'],['Không chắc chắn','Cần phân tích thêm để xác định.']].map(([t,d],i)=>`<label class="option ${state.wizard[step]===i?'selected':''}"><input type="radio" name="wizard-answer" value="${i}" ${state.wizard[step]===i?'checked':''}><span><strong>${t}</strong><small>${d}</small></span></label>`).join('')}<div class="explain" style="margin-top:17px"><strong style="color:var(--blue)">${icon('info')} Ví dụ minh họa</strong><p style="margin-top:5px">${q[3]}</p></div><div class="between" style="margin-top:20px"><button class="btn" data-action="wizard-back" ${step===0?'disabled':''}>‹ Quay lại</button><button class="btn primary" data-action="wizard-next" ${state.wizard[step]===undefined||state.wizard[step]===null?'disabled':''}>${step===4?'Xem kết quả':'Tiếp tục'} ${icon('arrow')}</button></div>`}</section><section class="card result-card"><div class="between"><h2>Kết quả đánh giá</h2>${badge(complete?'Hoàn tất':'Đang thực hiện','green',false)}</div>${complete?`<div class="result-illustration">${icon('chart')}</div><h2 style="text-align:center;color:var(--blue)">${rec[0]}</h2><p class="step-note" style="margin-top:15px">${rec[1]}</p>`:`<div class="result-illustration">📋</div><h3 style="text-align:center">Chưa có kết quả</h3><p class="step-note" style="text-align:center;margin-top:10px">Trả lời đủ 5 câu hỏi để nhận gợi ý phương pháp phù hợp.</p>`}<div class="result-summary"><div class="between"><h3>Tóm tắt câu trả lời</h3><strong>${answered}/5</strong></div>${questions.map((x,i)=>`<div class="result-row"><span class="avatar">${i+1}</span><span>${x[0]}</span>${badge(state.wizard[i]===undefined||state.wizard[i]===null?'Chưa trả lời':['Có','Một phần','Không','Chưa chắc'][state.wizard[i]],state.wizard[i]===undefined||state.wizard[i]===null?'gray':'',false)}</div>`).join('')}</div><div class="action-bar">${button('Lưu đánh giá','save-wizard','soft','save')}<button class="btn soft" data-action="export-wizard" ${complete?'':'disabled'}>${icon('download')} Xuất báo cáo</button></div></section></div>`;}
function permissions(){const rows=[['Xem dashboard tổng quan',1,1,1],['Xem thông tin bệnh nhân',1,1,1],['Điều phối bệnh nhân',1,1,1],['Duyệt gợi ý AI',1,1,1],['Cấu hình mô phỏng',1,1,1],['Quản lý người dùng',1,0,0],['Xem nhật ký hệ thống',1,1,1]];return `<table class="permissions"><thead><tr><th>Chức năng</th><th>Quản trị viên</th><th>Điều phối viên</th><th>Bác sĩ</th></tr></thead><tbody>${rows.map(([t,...r])=>`<tr><td>${t}</td>${r.map(v=>`<td><span class="${v?'ok':'no'}">${v?'✓':'×'}</span></td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function users(){let list=state.users.filter(u=>(u.name+' '+u.email+' '+u.department).toLowerCase().includes(state.userSearch.toLowerCase())&&(state.userRole==='Tất cả'||u.role===state.userRole)&&(state.userStatus==='Tất cả'||u.status===state.userStatus));return heading('Người dùng & Phân quyền','Quản lý tài khoản người dùng, vai trò và quyền truy cập hệ thống Smart OPD.')+`<div class="user-tabs">${[['users','Người dùng','users'],['roles','Vai trò','user'],['permissions','Phân quyền','shield']].map(([id,t,i])=>`<button class="btn ${state.userTab===id?'soft':''}" data-user-tab="${id}">${icon(i)}${t}</button>`).join('')}</div>${state.userTab==='users'?`<div class="filter-grid"><div class="search"><input id="user-search" value="${esc(state.userSearch)}" placeholder="Tìm theo họ tên, email hoặc khoa phòng..." aria-label="Tìm người dùng"></div><select id="user-role-filter" aria-label="Lọc vai trò">${['Tất cả','Quản trị viên','Điều phối viên','Bác sĩ'].map(x=>`<option value="${x}" ${state.userRole===x?'selected':''}>${x==='Tất cả'?'Tất cả vai trò':x}</option>`).join('')}</select><select id="user-status-filter" aria-label="Lọc trạng thái">${['Tất cả','Hoạt động','Tạm khóa'].map(x=>`<option value="${x}" ${state.userStatus===x?'selected':''}>${x==='Tất cả'?'Tất cả trạng thái':x}</option>`).join('')}</select>${button('Tạo người dùng','new-user','primary','plus')}</div><section class="card"><div class="card-head"><h2>Danh sách người dùng <span class="muted">(${list.length})</span></h2>${badge('Tài khoản người dùng','gray',false)}</div><div class="table-wrap"><table><thead><tr><th>Họ tên</th><th>Email / Tài khoản</th><th>Vai trò</th><th>Khoa / Phòng</th><th>Trạng thái</th><th>Lần đăng nhập cuối</th><th>Hành động</th></tr></thead><tbody>${list.map((u,i)=>`<tr><td><div class="flex">${avatar(u.name,i)}<strong>${esc(u.name)}</strong></div></td><td>${esc(u.email)}</td><td>${badge(u.role,u.role==='Quản trị viên'?'red':u.role==='Bác sĩ'?'green':'',false)}</td><td>${esc(u.department)}</td><td>${badge(u.status,u.status==='Hoạt động'?'green':'amber')}</td><td>14/10/2026 10:${24-i*3}</td><td><button class="icon-btn" data-edit-user="${u.id}" aria-label="Chỉnh sửa ${esc(u.name)}">${icon('edit')}</button></td></tr>`).join('')||'<tr><td colspan="7" class="table-empty">Không tìm thấy người dùng.</td></tr>'}</tbody></table></div></section><div style="height:18px"></div>${card('Ma trận phân quyền theo vai trò',permissions())}`:state.userTab==='roles'?`<div class="settings-grid">${[['Quản trị viên','crown','green','Quản lý tài khoản, cấu hình và phân quyền hệ thống.'],['Điều phối viên','users','','Theo dõi hàng đợi, điều phối và đánh giá gợi ý.'],['Bác sĩ','stethoscope','purple','Xem hồ sơ, cập nhật tiến trình và ghi chú khám.']].map(([t,i,c,d])=>`<section class="card setting-card">${circle(i,c)}<h2 style="margin-top:15px">${t}</h2><p>${d}</p>${badge(state.users.filter(u=>u.role===t).length+' người dùng',c,false)}</section>`).join('')}</div><div class="notice" style="margin-top:18px">${icon('info')} Phân quyền theo nhóm chức năng. Xem phạm vi triển khai tại Thông tin hệ thống.</div>`:card('Ma trận phân quyền theo vai trò',permissions(),badge('Theo vai trò','gray',false))}`;}
function logs(){let list=state.logs.filter(l=>(l.actor+' '+l.type+' '+l.detail).toLowerCase().includes(state.logSearch.toLowerCase()));return heading('Nhật ký hệ thống','Tra cứu lịch sử thao tác, thay đổi hồ sơ và quyết định điều phối.',button('Xuất nhật ký','export-logs','primary','download'))+`<section class="card"><div class="card-head"><h2>Lịch sử hoạt động <span class="muted">(${list.length})</span></h2><div class="search">${icon('search')}<input id="log-search" value="${esc(state.logSearch)}" placeholder="Tìm thao tác, người dùng..." aria-label="Tìm nhật ký"></div></div><div class="table-wrap"><table><thead><tr><th>Thời gian</th><th>Người thực hiện</th><th>Loại thao tác</th><th>Đối tượng</th><th>Chi tiết</th></tr></thead><tbody>${list.map(l=>`<tr><td>14/10/2026 ${esc(l.time)}</td><td><div class="flex">${avatar(l.actor)}${esc(l.actor)}</div></td><td>${badge(l.type,l.type.includes('AI')?'purple':l.type==='Cập nhật'?'green':'',false)}</td><td>${esc(l.object)}</td><td class="log-detail">${esc(l.detail)}</td></tr>`).join('')||'<tr><td colspan="5" class="table-empty">Không có hoạt động phù hợp.</td></tr>'}</tbody></table></div></section>`;}
function login(){return `<main class="login"><section class="login-left">${brand()}<h1>Kết nối hành trình khám.<br>Hỗ trợ từng quyết định.</h1><p>Smart OPD giúp bệnh viện theo dõi, dự báo và điều phối luồng bệnh nhân hiệu quả, an toàn và nhân văn hơn.</p><div class="login-features">${[['Theo dõi bệnh nhân thời gian thực','Nắm bắt toàn bộ luồng bệnh nhân trên một nền tảng duy nhất','users'],['Gợi ý hỗ trợ điều phối','Đưa ra khuyến nghị dựa trên dữ liệu vận hành','spark'],['Mô phỏng kịch bản vận hành','Dự báo tải, thử nghiệm trước khi triển khai','chart'],['SAS Wizard','Đánh giá phương pháp ra quyết định phù hợp','wand']].map(([t,d,i])=>`<div>${circle(i)}<span><h3>${t}</h3><p>${d}</p></span></div>`).join('')}</div>${hospitalArt('login-art')}<div class="login-quote">Smart OPD<br>Nền tảng quản lý và điều phối khám ngoại trú.</div></section><section class="login-right"><div class="login-card"><div class="tabs"><button class="tab active" data-action="login-tab">${icon('user')} Đăng nhập</button><button class="tab" data-action="demo-focus">${icon('play')} Chọn vai trò</button></div><h2>Chào mừng trở lại <span style="font-size:22px">👋</span></h2><p>Truy cập không gian quản lý và điều phối khám ngoại trú.</p><form class="login-form" id="login-form"><label class="field"><span>Email</span><input class="input" name="email" type="email" value="lan.nt@benhvien.vn" required autocomplete="username"></label><label class="field"><span class="between">Mật khẩu <button type="button" class="link small" data-action="forgot-password">Trợ giúp đăng nhập</button></span><span class="password-wrap"><input class="input" name="password" id="password" type="password" value="Opd@2026" required autocomplete="current-password"><button type="button" class="icon-btn" data-action="toggle-password" aria-label="Hiện hoặc ẩn mật khẩu">${icon('eye')}</button></span></label><div class="between small muted"><label class="flex"><input type="checkbox" checked disabled> Phiên làm việc cục bộ</label><span>Smart OPD</span></div><button type="submit" class="btn primary">Đăng nhập ${icon('arrow')}</button></form><div class="login-divider">hoặc mở không gian theo vai trò</div><div class="demo-box" id="demo-box"><h3>Không gian làm việc</h3><p>Chọn vai trò để truy cập các chức năng tương ứng.</p><div class="role-cards">${[['Quản trị viên','crown','green','Quản lý hệ thống, cấu hình vận hành và phân quyền.'],['Điều phối viên','users','soft','Theo dõi và điều phối luồng bệnh nhân.'],['Bác sĩ','stethoscope','purple','Quản lý hồ sơ và cập nhật tiến trình khám.']].map(([r,i,c,d])=>`<div class="role-card">${circle(i,c)}<h3>${r}</h3><p>${d}</p><button class="btn ${c}" data-demo-role="${r}">${icon('play')} Mở không gian</button></div>`).join('')}</div></div><div class="login-security"><span>${icon('shield')} Dữ liệu cục bộ</span><span>${icon('lock')} Lưu trên trình duyệt</span><span>${icon('file')} Hồ sơ & điều phối</span></div><p class="login-demo-note">Smart OPD · Quản lý và điều phối khám ngoại trú</p></div></section></main>`;}

function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
let previousFocus=null;
function modal(title,body,footer=''){previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Đóng">${icon('close')}</button></div>${body}${footer}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('.modal input,.modal select,.modal button')?.focus(),20);}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';previousFocus?.focus();}
function formModal(title,id,body,submit='Lưu thay đổi'){modal(title,`<form id="${id}"><div class="modal-body"><div class="form-grid">${body}</div></div><div class="modal-footer"><button type="button" class="btn" data-action="close-modal">Hủy</button><button class="btn primary" type="submit">${icon('save')} ${submit}</button></div></form>`);}
function field(label,name,value='',type='text',required=true,full=false){return `<label class="field ${full?'full':''}"><span>${label}${required?' <em>*</em>':''}</span><input class="input" name="${name}" value="${esc(value)}" type="${type}" ${required?'required':''} ${type==='number'?'min="0" max="120"':''} maxlength="150"></label>`;}
function selectField(label,name,options,value='',full=false){return `<label class="field ${full?'full':''}"><span>${label} <em>*</em></span><select name="${name}" required>${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;}
function newPatient(){formModal('Đăng ký bệnh nhân','patient-form',field('Họ và tên','name','','text',true,true)+field('Tuổi','age','','number')+selectField('Giới tính','gender',['Nữ','Nam'])+field('Số điện thoại','phone','','tel')+selectField('Mức ưu tiên','priority',['Bình thường','Cao','Thấp'])+selectField('Phòng khám','department',[...new Set(departments)].filter(x=>x!=='Chờ khám'&&x!=='Thu viện phí'),'Khám nội tổng quát',true),'Đăng ký bệnh nhân');$('#patient-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);let name=f.get('name').trim(),phone=f.get('phone').trim();if(!name||!/^[+\d\s().-]{8,18}$/.test(phone)){toast('Vui lòng nhập tên và số điện thoại hợp lệ.');return;}let max=Math.max(...state.patients.map(p=>Number(p.id.slice(2))));let p={id:'BN'+String(max+1).padStart(6,'0'),name,age:Number(f.get('age')),gender:f.get('gender'),phone,priority:f.get('priority'),department:f.get('department'),status:'Đang chờ',wait:0,completed:0,next:f.get('department'),room:'P.201',notes:[],date:'2026-10-14'};state.patients.unshift(p);state.search='';state.status='Tất cả';state.priority='Tất cả';state.dept='Tất cả';state.pageNumber=1;log('Tiếp nhận','Đăng ký bệnh nhân '+name,p.id);closeModal();render();toast('Đã đăng ký '+p.id+' — '+name);};}
function editUser(id){if(state.role!=='Quản trị viên'){toast('Chức năng dành cho quản trị viên.');return;}let u=state.users.find(x=>x.id===Number(id));formModal(u?'Chỉnh sửa người dùng':'Tạo người dùng','user-form',field('Họ và tên','name',u?.name||'','text',true,true)+field('Email / Tài khoản','email',u?.email||'','email')+selectField('Vai trò','role',['Quản trị viên','Điều phối viên','Bác sĩ'],u?.role)+field('Khoa / Phòng','department',u?.department||'')+selectField('Trạng thái','status',['Hoạt động','Tạm khóa'],u?.status));$('#user-form').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));Object.keys(f).forEach(k=>f[k]=f[k].trim());if(!f.name||!f.department){toast('Vui lòng điền đầy đủ thông tin.');return;}if(state.users.some(x=>x.email.toLowerCase()===f.email.toLowerCase()&&x.id!==u?.id)){toast('Email này đã tồn tại.');return;}if(u)Object.assign(u,f);else state.users.push({id:Date.now(),...f});log('Phân quyền',(u?'Cập nhật':'Tạo')+' tài khoản '+f.name);closeModal();render();toast('Đã lưu thông tin người dùng.');};}
function transfer(id,override=false){let p=state.patients.find(p=>p.id===id);if(!p)return;formModal(override?'Ghi đè gợi ý thủ công':'Điều phối bệnh nhân','transfer-form',`<p style="grid-column:1/-1">${esc(p.id)} — <strong>${esc(p.name)}</strong></p>`+selectField('Phòng đích','room',['P.201 — Nội tổng quát 2','P.305 — Nội tổng quát 3','P.102 — Siêu âm','P.108 — X-quang','P.204 — Xét nghiệm'],'',true)+`<label class="field full"><span>Lý do điều phối <em>*</em></span><textarea name="reason" required maxlength="200" placeholder="Nhập lý do chuyển phòng..."></textarea></label>`,'Xác nhận điều phối');$('#transfer-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),reason=f.get('reason').trim();if(!reason){toast('Vui lòng nhập lý do điều phối.');return;}let [room,dept]=f.get('room').split(' — ');p.room=room;p.department=dept;p.next=dept;p.status='Đang chờ';p.wait=0;if(override)addDecision(p,'Ghi đè thủ công',reason+' · '+room);log('Điều phối','Chuyển '+p.name+' đến '+room+'. Lý do: '+reason,p.id);closeModal();render();toast('Đã chuyển bệnh nhân đến '+room);};}
function addDecision(p,status,reason=''){state.decisions.unshift({patientId:p.id,name:p.name,status,reason,time:new Date().toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Ho_Chi_Minh'})});persist();}
function processAI(action){let p=aiPatients()[state.aiIndex]||aiPatients()[0];if(!p)return;if(state.decisions.some(d=>d.patientId===p.id)){toast('Gợi ý này đã được xử lý.');return;}if(action==='override-ai'){transfer(p.id,true);return;}if(action==='reject-ai'){formModal('Từ chối gợi ý','reject-form',`<label class="field full"><span>Lý do từ chối <em>*</em></span><textarea name="reason" required maxlength="200" placeholder="Ví dụ: phòng đích không phù hợp chuyên khoa..."></textarea></label>`,'Xác nhận từ chối');$('#reject-form').onsubmit=e=>{e.preventDefault();let reason=new FormData(e.target).get('reason').trim();if(!reason)return;addDecision(p,'Từ chối',reason);log('Quyết định AI','Từ chối gợi ý cho '+p.name+': '+reason,p.id);closeModal();render();toast('Đã lưu quyết định từ chối.');};return;}addDecision(p,'Đã chấp nhận','Chuyển đến P.201');p.room='P.201';p.next='Nội tổng quát 2';p.wait=Math.max(0,p.wait-18);log('Quyết định AI','Chấp nhận gợi ý chuyển '+p.name+' đến P.201',p.id);state.aiIndex=aiPatients().findIndex(x=>x.id===p.id);render();toast('Đã áp dụng gợi ý và cập nhật phòng tiếp theo.');}
function invalidateSim(){state.sim.result=null;state.sim.progress=0;if(simTimer)clearInterval(simTimer);state.sim.running=false;}
function configureScenario(index){if(state.sim.running){toast('Tạm dừng mô phỏng trước khi đổi cấu hình.');return;}invalidateSim();Object.assign(state.sim,{count:1248,queue:'Static',ai:false,hours:8,resources:[4,12,6,4,3],scenario:index});if(index===1)state.sim.count=1498;if(index===2)state.sim.resources[1]=14;if(index===3)state.sim.queue='Priority';if(index===4)state.sim.ai=true;if(index===5)state.sim.resources[2]=9;if(index>=6){let saved=state.scenarios[index-6];if(saved)Object.assign(state.sim,structuredClone(saved.config),{scenario:index,progress:0,result:null,running:false});}render();}
function runSim(){if(state.sim.running)return;let s=state.sim;if(s.progress===100)s.progress=0;s.running=true;render();simTimer=setInterval(()=>{s.progress=Math.min(100,s.progress+4);if(state.page==='simulation'){$('#sim-bar').style.width=s.progress+'%';$('#sim-percent').textContent=s.progress+'%';}if(s.progress===100){clearInterval(simTimer);s.running=false;const capacity=s.resources[1]*s.hours*14+s.resources[2]*s.hours*2;const pressure=s.count/capacity;const improvement=s.ai?35:s.queue==='Priority'?15:0;let wait=Math.max(5,Math.round(43*pressure*(1-improvement/100)));s.result={count:s.count,wait,los:wait+24,overload:Math.max(0,Math.min(99,Math.round((pressure-.7)*40))),completed:Math.min(s.count,Math.round(capacity*(s.ai?1.15:1))),improvement};log('Mô phỏng',`Hoàn tất mô phỏng ${s.count} bệnh nhân, ${s.hours} giờ. Thời gian chờ: ${wait} phút.`,'KB'+(s.scenario+1));if(state.page==='simulation')render();toast('Mô phỏng hoàn tất. Kết quả đã sẵn sàng.');}},160);}
function saveScenario(fresh=false){formModal(fresh?'Tạo kịch bản mới':'Lưu kịch bản mô phỏng','scenario-form',field('Tên kịch bản','name',fresh?'':'Kịch bản '+(state.scenarios.length+1),'text',true,true)+`<p style="grid-column:1/-1">Lưu cấu hình hiện tại: ${state.sim.count} bệnh nhân, ${state.sim.hours} giờ, ${state.sim.queue}.</p>`,'Lưu kịch bản');$('#scenario-form').onsubmit=e=>{e.preventDefault();let name=new FormData(e.target).get('name').trim();if(!name)return;let config=structuredClone(state.sim);config.running=false;config.progress=0;config.result=null;state.scenarios.push({name,config});state.sim.scenario=baseScenarios.length+state.scenarios.length-1;log('Mô phỏng','Lưu kịch bản “'+name+'”');closeModal();render();toast('Đã lưu kịch bản.');};}
function download(name,rows){const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"').join(',')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất '+name);}
function exportReport(type){if(type==='patients')download('smart-opd-benh-nhan.csv',[['Mã BN','Họ tên','Tuổi','Giới tính','Phòng','Ưu tiên','Trạng thái','Thời gian chờ'],...filteredPatients().map(p=>[p.id,p.name,p.age,p.gender,p.department,p.priority,p.status,p.wait])]);if(type==='dashboard')download('smart-opd-bao-cao.csv',[['Báo cáo Smart OPD','Dữ liệu cục bộ'],['Kỳ báo cáo',state.period],['Ngày','14/10/2026'],['Tổng bệnh nhân',1248],['Đã hoàn tất',892],['Thời gian chờ TB (phút)',28],['Mức cải thiện AI (%)',41],[],['Khoa / Phòng','Tổng BN','Đã hoàn tất','Thời gian chờ TB'],...departmentsData.map(r=>r.slice(0,4))]);if(type==='logs')download('smart-opd-nhat-ky.csv',[['Thời gian','Người thực hiện','Loại thao tác','Đối tượng','Chi tiết'],...state.logs.map(l=>[l.time,l.actor,l.type,l.object,l.detail])]);if(type==='wizard'){if(state.wizardStep!==5)return;download('smart-opd-danh-gia-sas.csv',[['Câu hỏi','Câu trả lời'],...questions.map((q,i)=>[q[0],['Có','Một phần','Không','Không chắc'][state.wizard[i]]]),['Khuyến nghị',wizardRecommendation()[0]],['Lưu ý','Quy tắc đánh giá tham khảo']]);}if(type==='sim'){let r=state.sim.result;if(!r){toast('Hãy chạy mô phỏng để tạo kết quả trước.');return;}download('smart-opd-ket-qua-mo-phong.csv',[['Chỉ số','Giá trị'],['Bệnh nhân',r.count],['Thời gian mô phỏng (giờ)',state.sim.hours],['Thời gian chờ TB',r.wait],['LoS TB',r.los],['Tỷ lệ quá tải (%)',r.overload],['Bệnh nhân hoàn tất',r.completed],['Lưu ý','Mô hình tính toán minh họa']]);}}
function liveFilter(selector,update){let el=$(selector);if(!el)return;el.addEventListener('input',e=>{let start=e.target.selectionStart;update(e.target.value);render();let next=$(selector);next.focus();next.setSelectionRange(start,start);});}
function bindPage(){if($('#role-select'))$('#role-select').onchange=e=>{state.role=e.target.value;sessionStorage.setItem('opd-role',state.role);if(state.page==='users'&&state.role!=='Quản trị viên')navigate('dashboard');else render();toast('Đã chuyển sang vai trò '+state.role);};if($('#global-search'))$('#global-search').onsubmit=e=>{e.preventDefault();state.search=new FormData(e.target).get('q').trim();state.status='Tất cả';state.dept='Tất cả';state.priority='Tất cả';state.pageNumber=1;navigate('patients');};liveFilter('#patient-search',v=>{state.search=v;state.pageNumber=1;});liveFilter('#user-search',v=>state.userSearch=v);liveFilter('#log-search',v=>state.logSearch=v);[['#patient-status','status'],['#patient-priority','priority'],['#patient-dept','dept'],['#user-role-filter','userRole'],['#user-status-filter','userStatus']].forEach(([sel,key])=>{if($(sel))$(sel).onchange=e=>{state[key]=e.target.value;state.pageNumber=1;render();};});if($('#note-form'))$('#note-form').onsubmit=e=>{e.preventDefault();let note=new FormData(e.target).get('note').trim();if(!note)return;let p=currentPatient();p.notes.unshift({text:note,time:new Date().toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Ho_Chi_Minh'})});log('Ghi chú','Thêm ghi chú cho '+p.name,p.id);render();toast('Đã lưu ghi chú.');};$$('[name="wizard-answer"]').forEach(el=>el.onchange=e=>{state.wizard[state.wizardStep]=Number(e.target.value);render();});if($('#sim-count'))$('#sim-count').oninput=e=>{invalidateSim();state.sim.count=Number(e.target.value);$('#patient-count').textContent=state.sim.count.toLocaleString('vi-VN');};if($('#sim-count'))$('#sim-count').onchange=()=>render();$$('[data-resource]').forEach(el=>{el.oninput=e=>{invalidateSim();let i=Number(e.target.dataset.resource);state.sim.resources[i]=Number(e.target.value);$('#resource-'+i).textContent=e.target.value;};el.onchange=()=>render();});if($('#sim-ai'))$('#sim-ai').onchange=e=>{invalidateSim();state.sim.ai=e.target.checked;render();};if($('#login-form'))$('#login-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);if(f.get('email')==='lan.nt@benhvien.vn'&&['Opd@2026','demo123'].includes(f.get('password'))){state.role='Quản trị viên';sessionStorage.setItem('opd-role',state.role);navigate('dashboard');toast('Đã mở không gian làm việc Smart OPD.');}else toast('Tài khoản mặc định: lan.nt@benhvien.vn / Opd@2026');};['#dashboard-dept','#dashboard-shift','#dashboard-date'].forEach(sel=>{if($(sel))$(sel).onchange=e=>{toast('Bộ dữ liệu mẫu hiện chỉ có báo cáo tổng hợp ngày 14/10/2026.');if(e.target.tagName==='SELECT')e.target.selectedIndex=0;else e.target.value='2026-10-14';};});}
document.addEventListener('click',e=>{let el=e.target.closest('button,[data-status]');if(!el)return;
 if(el.dataset.patient){state.patientId=el.dataset.patient;navigate('detail');return;}
 if(el.dataset.patientAi){state.aiTarget=el.dataset.patientAi;state.aiIndex=Math.max(0,aiPatients().findIndex(p=>p.id===el.dataset.patientAi));navigate('ai');return;}
 if(el.dataset.transfer){transfer(el.dataset.transfer);return;}
 if(el.dataset.complete){let p=state.patients.find(x=>x.id===el.dataset.complete);if(p&&p.completed<21){p.completed++;if(p.completed===21){p.status='Hoàn tất';p.wait=0;}log('Cập nhật','Hoàn tất hoạt động '+p.completed+'/21 cho '+p.name,p.id);render();toast('Đã cập nhật tiến trình.');}return;}
 if(el.dataset.status){state.status=el.dataset.status;state.pageNumber=1;render();return;}
 if(el.dataset.page){state.pageNumber=Number(el.dataset.page);render();return;}
 if(el.dataset.period){state.period=el.dataset.period;render();return;}
 if(el.dataset.metric){state.metric=el.dataset.metric;render();return;}
 if(el.dataset.queue){state.dept=el.dataset.queue;state.status='Tất cả';state.search='';navigate('patients');return;}
 if(el.dataset.aiIndex!==undefined){state.aiIndex=Number(el.dataset.aiIndex);render();return;}
 if(el.dataset.queueType){invalidateSim();state.sim.queue=el.dataset.queueType;render();return;}
 if(el.dataset.hours){invalidateSim();state.sim.hours=Number(el.dataset.hours);render();return;}
 if(el.dataset.scenario){configureScenario(Number(el.dataset.scenario));return;}
 if(el.dataset.wizardStep){state.wizardStep=Number(el.dataset.wizardStep);render();return;}
 if(el.dataset.userTab){state.userTab=el.dataset.userTab;render();return;}
 if(el.dataset.editUser){editUser(el.dataset.editUser);return;}
 if(el.dataset.demoRole){state.role=el.dataset.demoRole;sessionStorage.setItem('opd-role',state.role);navigate('dashboard');toast('Đã chuyển sang vai trò '+state.role);return;}
 const action=el.dataset.action;if(!action)return;
 if(navItems.some(n=>n[0]===action)){if(action==='users'&&state.role!=='Quản trị viên'){toast('Chuyển sang vai trò Quản trị viên để quản lý người dùng.');return;}navigate(action);return;}
 if(action.startsWith('export-')){exportReport(action.replace('export-',''));return;}
 switch(action){
 case 'close-modal':closeModal();break;
 case 'menu':$('#sidebar').classList.toggle('open');break;
 case 'profile':modal('Tài khoản người dùng',`<div class="modal-body"><div class="flex">${avatar('Nguyễn Thị Lan')}<div><h2>Nguyễn Thị Lan</h2><p style="margin:5px 0">${state.role} · lan.nt@benhvien.vn</p></div></div><p style="margin-top:20px">Dữ liệu phiên làm việc được lưu trong trình duyệt hiện tại.</p></div>`,`<div class="modal-footer">${button('Về màn hình đăng nhập','logout','','logout')}</div>`);break;
 case 'logout':closeModal();navigate('login');break;
 case 'notifications':modal('Thông báo vận hành',`<div class="modal-body">${alerts()}<p style="margin:15px 0 0">Các thông báo này thuộc bộ dữ liệu minh họa.</p></div>`);break;
 case 'resources':modal('Tài nguyên & phòng chức năng',`<div class="modal-body">${resourcesTable()}</div>`);break;
 case 'security':modal('Thông tin bảo mật',`<div class="modal-body">${securityRows()}<p style="margin:16px 0 0">Phiên bản hiện tại chưa có xác thực máy chủ, sao lưu tập trung hoặc đánh giá tuân thủ. Không nhập dữ liệu y tế thật.</p></div>`);break;
 case 'reset-filters':state.search='';state.status='Tất cả';state.priority='Tất cả';state.dept='Tất cả';state.pageNumber=1;render();break;
 case 'new-patient':newPatient();break;
 case 'new-user':editUser();break;
 case 'detail-transfer':transfer(currentPatient().id);break;
 case 'detail-ai':state.aiTarget=currentPatient().id;state.aiIndex=Math.max(0,aiPatients().findIndex(x=>x.id===currentPatient().id));navigate('ai');break;
 case 'print':window.print();break;
 case 'accept-ai':case 'override-ai':case 'reject-ai':processAI(action);break;
 case 'run-sim':runSim();break;
 case 'pause-sim':if(state.sim.running){clearInterval(simTimer);state.sim.running=false;render();toast('Đã tạm dừng mô phỏng.');}else toast('Mô phỏng hiện chưa chạy.');break;
 case 'reset-sim':clearInterval(simTimer);state.sim={count:1248,queue:'Static',ai:true,hours:8,resources:[4,12,6,4,3],scenario:0,progress:0,running:false,result:null};render();break;
 case 'save-scenario':saveScenario();break;
 case 'new-scenario':saveScenario(true);break;
 case 'wizard-help':modal('Hướng dẫn SAS Wizard',`<div class="modal-body"><p>1. Trả lời từng câu hỏi theo đặc điểm quy trình của bạn.</p><p>2. Dùng nút “Quay lại” hoặc số câu hỏi để sửa lựa chọn.</p><p>3. Sau câu 5, nhấn “Xem kết quả” để xem phương pháp được gợi ý.</p><p>4. Lưu đánh giá trên trình duyệt hoặc xuất CSV để trao đổi với nhóm triển khai.</p><div class="notice">${icon('info')} Kết quả dùng quy tắc chấm điểm minh họa, cần chuyên gia xác nhận trước khi áp dụng.</div></div>`);break;
 case 'wizard-next':if(state.wizard[state.wizardStep]!==undefined&&state.wizard[state.wizardStep]!==null){state.wizardStep=Math.min(5,state.wizardStep+1);if(state.wizardStep===5){let missing=questions.findIndex((_,i)=>state.wizard[i]===undefined||state.wizard[i]===null);if(missing!==-1){state.wizardStep=missing;toast('Vui lòng trả lời đủ 5 câu hỏi để nhận kết quả.');}else{persist();log('SAS Wizard','Hoàn tất đánh giá: '+wizardRecommendation()[0]);}}render();}break;
 case 'wizard-back':state.wizardStep=Math.max(0,state.wizardStep-1);render();break;
 case 'restart-wizard':state.wizard=[];state.wizardStep=0;persist();render();break;
 case 'save-wizard':persist();toast('Đã lưu câu trả lời trên trình duyệt.');break;
 case 'toggle-password':$('#password').type=$('#password').type==='password'?'text':'password';break;
 case 'forgot-password':modal('Tài khoản trải nghiệm',`<div class="modal-body"><p>Email: <strong>lan.nt@benhvien.vn</strong><br>Mật khẩu: <strong>Opd@2026</strong></p><p>Hoặc chọn “Mở không gian” theo vai trò. Chức năng đăng nhập SSO và khôi phục tài khoản thật chưa được kết nối.</p></div>`);break;
 case 'demo-focus':$('#demo-box').scrollIntoView({behavior:'smooth',block:'center'});$('#demo-box button').focus();break;
 case 'login-tab':$('#login-form input').focus();break;
 }
});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-overlay'))closeModal();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('#sidebar')?.classList.remove('open');}if(e.key==='Tab'&&$('.modal')){let focusable=$$('button,input,select,textarea,a[href]', $('.modal')).filter(x=>!x.disabled);let first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{syncRoute();window.scrollTo(0,0);});
window.addEventListener('beforeunload',()=>{if(simTimer)clearInterval(simTimer);});
syncRoute();
